{
  "findings": [
    {
      "check_id": "CKV_AWS_16",
      "title": "RDS storage encryption is not enabled",
      "resource": "aws_db_instance.levelup-rds",
      "severity": "HIGH",
      "explanation": "The instance does not set storage_encrypted, so its database storage is unencrypted by default. This exposes data at rest, including automated backups and snapshots, if the underlying storage is accessed."
    },
    {
      "check_id": "CKV_AWS_157",
      "title": "RDS Multi-AZ deployment is disabled",
      "resource": "aws_db_instance.levelup-rds",
      "severity": "MEDIUM",
      "explanation": "The instance explicitly disables Multi-AZ deployment, leaving the database without a synchronous standby in another availability zone. An availability-zone failure could therefore cause extended downtime."
    },
    {
      "check_id": "CKV_AWS_293",
      "title": "RDS deletion protection is not enabled",
      "resource": "aws_db_instance.levelup-rds",
      "severity": "MEDIUM",
      "explanation": "Deletion protection is not configured and therefore defaults to disabled. The database can be accidentally or maliciously deleted without the additional RDS deletion safeguard."
    }
  ],
  "patched_code": "resource \"aws_db_instance\" \"levelup-rds\" {\n  identifier               = \"${var.ENVIRONMENT}-levelup-rds\"\n  allocated_storage        = var.LEVELUP_RDS_ALLOCATED_STORAGE\n  storage_type             = \"gp2\"\n  storage_encrypted        = true\n  engine                   = var.LEVELUP_RDS_ENGINE\n  engine_version           = var.LEVELUP_RDS_ENGINE_VERSION\n  instance_class           = var.DB_INSTANCE_CLASS\n  backup_retention_period  = var.BACKUP_RETENTION_PERIOD\n  publicly_accessible      = var.PUBLICLY_ACCESSIBLE\n  username                 = var.LEVELUP_RDS_USERNAME\n  password                 = var.LEVELUP_RDS_PASSWORD\n  vpc_security_group_ids   = [aws_security_group.levelup-rds-sg.id]\n  db_subnet_group_name     = aws_db_subnet_group.levelup-rds-subnet-group.name\n  multi_az                 = true\n  deletion_protection      = true\n}\n",
  "fix_summary": "Enabled RDS storage encryption, Multi-AZ deployment, and deletion protection. All existing resource settings and variable references were retained."
}
